  /** @minLength 1 */
  title: string;
  type: SessionType;
  /** @pattern ^\d{4}-\d{2}-\d{2}$ */
  scheduledDate: string;
  /** @nullable */
  startTime?: string | null;
  /**
     * @minimum 15
     * @maximum 480
     */
  durationMinutes?: number;
  /** @nullable */
  facilitator?: string | null;
  /** @nullable */
  trainerStaffId?: number | null;
  deliveryMode?: DeliveryMode;
  /** @nullable */
  location?: string | null;
  /** @nullable */
  zoomUrl?: string | null;
  /** @nullable */
